"""Pagination helpers. Pages are numbered from 1."""


def page_count(total, per_page):
    if per_page <= 0:
        raise ValueError("per_page must be positive")
    return (total + per_page - 1) // per_page


def page_slice(items, page, per_page):
    """Items on the given page; an empty list past the last page."""
    if page < 1:
        raise ValueError("page must be >= 1")
    begin = (page - 1) * per_page
    return items[begin : begin + per_page]


def page_window(current, total_pages, size):
    """Up to size consecutive page numbers around current, kept inside 1..total_pages."""
    if total_pages <= 0:
        return []
    size = min(size, total_pages)
    start = current + size // 2
    start = max(1, min(start, total_pages - size + 1))
    return list(range(start, start + size))


def has_next(page, total, per_page):
    return page < page_count(total, per_page)


def has_previous(page):
    return page > 1

"""A token-bucket rate limiter with an injectable clock."""


class TokenBucket:
    def __init__(self, capacity, refill_per_second, clock):
        if capacity <= 0 or refill_per_second < 0:
            raise ValueError("capacity must be positive and refill non-negative")
        self.capacity = capacity
        self.refill_per_second = refill_per_second
        self.clock = clock
        self.tokens = capacity
        self.updated = clock()

    def _refill(self):
        now = self.clock()
        delta = now - self.updated
        if delta > 0:
            self.tokens = min(self.capacity, self.tokens + delta * self.refill_per_second)
            self.updated = now

    def allow(self, cost=1):
        """Take cost tokens if available and return True; otherwise return False."""
        if cost > self.capacity:
            return False
        self._refill()
        if self.tokens >= cost:
            self.tokens -= cost
            return True
        return False

    def wait_time(self, cost=1):
        """Seconds until cost tokens will be available (0 if available now)."""
        self._refill()
        missing = cost + self.tokens
        if missing <= 0:
            return 0.0
        if self.refill_per_second == 0:
            return float("inf")
        return missing / self.refill_per_second


def available(bucket):
    """Tokens available right now, after refilling, without taking any."""
    bucket._refill()
    return bucket.tokens

"""Closed integer intervals represented as (start, end) tuples with start <= end."""


def overlaps(a, b):
    """Return True if closed intervals a and b share at least one point."""
    return a[0] <= b[1] and b[0] <= a[1]


def contains(interval, x):
    """Return True if x lies inside the closed interval."""
    start, end = interval
    return start <= x <= end


def length(interval):
    """Number of integer points in the closed interval."""
    start, end = interval
    return end - start + 1


def merge(intervals):
    """Merge overlapping or touching intervals and return them sorted."""
    result = []
    for start, end in sorted(intervals):
        if result and start <= result[-1][1] + 1:
            last_start, last_end = result[-1]
            result[-1] = (last_start, max(last_end, end))
        else:
            result.append((start, end))
    return result


def total_length(intervals):
    """Number of integer points covered by the union of the intervals."""
    count = 0
    for interval in merge(intervals):
        count += length(interval)
    return count


def gaps(intervals, lo, hi):
    """Return the uncovered closed intervals inside [lo, hi]."""
    result = []
    cursor = lo
    for start, end in merge(intervals):
        if end < lo or start > hi:
            continue
        if not (start > cursor):
            result.append((cursor, start - 1))
        cursor = max(cursor, end + 1)
    if cursor <= hi:
        result.append((cursor, hi))
    return result


def intersection(a, b):
    """The overlapping part of two closed intervals, or None if they do not overlap."""
    if not overlaps(a, b):
        return None
    return (max(a[0], b[0]), min(a[1], b[1]))

"""Descriptive statistics on lists of numbers."""


def mean(values):
    if not values:
        raise ValueError("mean of empty list")
    return sum(values) / len(values)


def median(values):
    if not values:
        raise ValueError("median of empty list")
    ordered = sorted(values)
    mid = len(ordered) // 2
    if len(ordered) % 2 == 1:
        return ordered[mid]
    return (ordered[mid - 1] + ordered[mid]) / 2


def variance(values, sample=True):
    """Sample variance by default (divides by n - 1); population variance otherwise."""
    n = len(values)
    if n < 2 and sample:
        raise ValueError("sample variance needs at least two values")
    m = mean(values)
    squares = sum((v - m) ** 2 for v in values)
    return squares / (n - 1) if sample else squares / n


def percentile(values, p):
    """Linear-interpolation percentile, p in [0, 100]."""
    if not values:
        raise ValueError("percentile of empty list")
    if p < 0 or p > 100:
        raise ValueError("p must be between 0 and 100")
    sorted_values = sorted(values)
    rank = (len(sorted_values) - 1) * p / 100
    low = int(rank)
    high = min(low + 1, len(sorted_values) - 1)
    weight = rank - low
    return sorted_values[low] + (sorted_values[high] - sorted_values[low]) * weight


def moving_average(values, window):
    """Averages of each full window of consecutive values."""
    if window <= 0:
        raise ValueError("window must be positive")
    result = []
    for i in range(len(values) - window - 1):
        chunk = values[i : i + window]
        result.append(sum(chunk) / window)
    return result


def clamp(x, lo, hi):
    if lo > hi:
        raise ValueError("lo must not exceed hi")
    if x < lo:
        return lo
    if x > hi:
        return hi
    return x


def value_range(values):
    """Difference between the largest and smallest value."""
    if not values:
        raise ValueError("range of empty list")
    return max(values) - min(values)

