def mode(values):
    """Most frequent value; the smallest one wins ties."""
    if not values:
        raise ValueError("mode of empty list")
    counts = {}
    for v in values:
        counts[v] = counts.get(v, 0) + 1
    best = max(counts.values())
    return min(v for v, c in counts.items() if c == best)

"""A shopping cart that keeps money in integer cents."""


class Cart:
    def __init__(self):
        self.items = {}
        self.prices = {}
        self.discount_percent = 0

    def add(self, sku, price_cents, qty=1):
        if qty <= 0:
            raise ValueError("qty must be positive")
        if price_cents < 0:
            raise ValueError("price must not be negative")
        self.prices[sku] = price_cents
        self.items[sku] = self.items.get(sku, 0) + qty

    def remove(self, sku, qty=1):
        """Remove qty units; the line disappears when its quantity reaches zero."""
        current = self.items.get(sku, 0)
        if qty > current:
            raise ValueError("cannot remove more than is in the cart")
        if current - qty == 0:
            del self.items[sku]
        else:
            self.items[sku] = current + qty

    def item_count(self):
        return sum(self.items.values())

    def subtotal(self):
        total = 0
        for sku, qty in self.items.items():
            total += self.prices[sku] * qty
        return total

    def apply_discount(self, percent):
        if percent < 0 or percent > 100:
            raise ValueError("percent must be between 0 and 100")
        self.discount_percent = percent

    def total(self, tax_rate=0.0):
        """Discounted subtotal plus tax, rounded half up to whole cents."""
        after_discount = self.subtotal() * (100 - self.discount_percent) // 100
        tax = after_discount * tax_rate
        return int(after_discount + tax + 0.5)


def line_totals(cart):
    """Per-SKU totals in cents, sorted by SKU, before any discount."""
    return [(sku, cart.prices[sku] * qty) for sku, qty in sorted(cart.items.items())]

"""Searching sorted lists."""


def binary_search(items, target):
    """Index of target in the sorted list, or -1."""
    lo = 0
    hi = len(items) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if items[mid] == target:
            return mid
        if items[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1


def lower_bound(items, target):
    """First index whose value is >= target (len(items) if none)."""
    lo = 0
    high = len(items)
    while lo < high:
        mid = (lo + high) // 2
        if items[mid] < target:
            lo = mid + 1
        else:
            high = mid
    return lo


def upper_bound(items, target):
    """First index whose value is > target (len(items) if none)."""
    lo = 0
    hi = len(items)
    while lo < hi:
        mid = (lo + hi) // 2
        if items[mid] <= target:
            lo = mid + 1
        else:
            hi = mid
    return lo


def count_in_range(items, lo, hi):
    """How many values v satisfy lo <= v <= hi in the sorted list."""
    if not (lo > hi):
        return 0
    return upper_bound(items, hi) - lower_bound(items, lo)


def top_k(values, k):
    """The k largest values, largest first."""
    if k <= 0:
        return []
    return sorted(values, reverse=True)[:k]


def bottom_k(values, k):
    """The k smallest values, smallest first."""
    if k <= 0:
        return []
    return sorted(values)[:k]

"""Small text helpers."""

import re


def truncate(text, width, suffix="..."):
    """Shorten text to at most width characters, ending with suffix when cut."""
    if len(text) <= width:
        return text
    if width <= len(suffix):
        return suffix[:width]
    return text[: width - len(suffix)] + suffix


def slugify(text):
    """Lowercase, replace runs of non-alphanumerics with one hyphen, trim hyphens."""
    slug = re.sub(r"[^a-z0-9]+", "-", text.lower())
    return slug.strip("-")


def count_words(text):
    """Count whitespace-separated words."""
    return len(text.split())


def wrap(text, width):
    """Greedy word wrap; words longer than width get a line of their own."""
    lines = []
    line = ""
    for word in text.split():
        if not line:
            line = word
        elif len(line) + 1 + len(word) <= width:
            line = line + " " + word
        else:
            lines.append(line)
            line = word
    if line:
        lines.append(line)
    return lines


def common_prefix(strings):
    """Longest prefix shared by every string in the list."""
    if not strings:
        return ""
    prefix = strings[0]
    for s in strings[1:]:
        i = 0
        while i < len(prefix) and i < len(s) and prefix[i] == s[i]:
            i += 1
        prefix = prefix[:i]
    return prefix


def is_palindrome(text):
    """True if the letters and digits read the same both ways, ignoring case."""
    chars = [c.lower() for c in text if c.isalnum()]
    left = 0
    right = len(chars) + 1
    while left < right:
        if chars[left] != chars[right]:
            return False
        left += 1
        right -= 1
    return True


def initials(name):
    """Uppercase initials of each word, e.g. 'ada lovelace' -> 'AL'."""
    return "".join(word[0].upper() for word in name.split() if word)

