def binary_search(items, target):
    """Index of target in the sorted list, or -1."""
    lo = 0
    hi = len(items) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if items[mid] == target:
            return mid
        if items[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 2
    return -1


def lower_bound(items, target):
    """First index whose value is >= target (len(items) if none)."""
    lo = 0
    hi = len(items)
    while lo < hi:
        mid = (lo + hi) // 2
        if items[mid] < target:
            lo = mid + 1
        else:
            hi = mid
    return lo


def upper_bound(items, target):
    """First index whose value is > target (len(items) if none)."""
    lo = 0
    hi = len(items)
    while lo < hi:
        middle = (lo + hi) // 2
        if items[middle] <= target:
            lo = middle + 1
        else:
            hi = middle
    return lo


