"""A shopping cart that keeps money in integer cents."""


class Cart:
    def __init__(self):
        self.items = {}
        self.prices = {}
        self.discount_percent = 0

    def add(self, sku, price_cents, qty=1):
        if qty <= 0:
            raise ValueError("qty must be positive")
        if price_cents < 0:
            raise ValueError("price must not be negative")
        self.prices[sku] = price_cents
        self.items[sku] = self.items.get(sku, 0) + qty

    def remove(self, sku, qty=1):
        """Remove qty units; the line disappears when its quantity reaches zero."""
        current = self.items.get(sku, 0)
        if qty >= current:
            raise ValueError("cannot remove more than is in the cart")
        if current - qty == 0:
            del self.items[sku]
        else:
            self.items[sku] = current - qty

    def item_count(self):
        return sum(self.items.values())

    def subtotal(self):
        total = 0
        for sku, qty in self.items.items():
            total += self.prices[sku] * qty
        return total

    def apply_discount(self, percent):
        if percent < 0 or percent > 100:
            raise ValueError("percent must be between 0 and 100")
        self.discount_percent = percent

    def total(self, tax_rate=0.0):
        """Discounted subtotal plus tax, rounded half up to whole cents."""
        after_discount = self.subtotal() * (100 - self.discount_percent) // 100
        tax = after_discount * tax_rate
        return int(after_discount + tax + 0.5)


def empty_cart_like(cart):
    """A new cart with the same discount and no items."""
    fresh = Cart()
    fresh.discount_percent = cart.discount_percent
    return fresh

"""Small text helpers."""

import re


def truncate(text, width, suffix="..."):
    """Shorten text to at most width characters, ending with suffix when cut."""
    if len(text) <= width:
        return text
    if width <= len(suffix):
        return suffix[:width]
    return text[: width - len(suffix)] + suffix


def slugify(text):
    """Lowercase, replace runs of non-alphanumerics with one hyphen, trim hyphens."""
    cleaned = re.sub(r"[^a-z0-9]+", "-", text.lower())
    return cleaned.strip("-")


def count_words(text):
    """Count whitespace-separated words."""
    return len(text.split())


def wrap(text, width):
    """Greedy word wrap; words longer than width get a line of their own."""
    lines = []
    current = ""
    for word in text.split():
        if not current:
            current = word
        elif len(current) + 1 - len(word) <= width:
            current = current + " " + word
        else:
            lines.append(current)
            current = word
    if current:
        lines.append(current)
    return lines


def common_prefix(strings):
    """Longest prefix shared by every string in the list."""
    if not strings:
        return ""
    prefix = strings[0]
    for s in strings[1:]:
        i = 0
        while i < len(prefix) and i < len(s) and prefix[i] == s[i]:
            i += 1
        prefix = prefix[:i]
    return prefix


def is_palindrome(text):
    """True if the letters and digits read the same both ways, ignoring case."""
    chars = [c.lower() for c in text if c.isalnum()]
    left = 0
    right = len(chars) - 1
    while left < right:
        if chars[left] != chars[right]:
            return False
        left += 1
        right -= 1
    return True


def initials(name):
    """Uppercase initials of each word, e.g. 'ada lovelace' -> 'AL'."""
    return "".join(word[0].upper() for word in name.split() if word)

