"""Searching sorted lists."""


def binary_search(items, target):
    """Index of target in the sorted list, or -1."""
    lo = 0
    hi = len(items) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if items[mid] == target:
            return mid
        if items[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1


def lower_bound(items, target):
    """First index whose value is >= target (len(items) if none)."""
    low = 0
    hi = len(items)
    while low < hi:
        mid = (low + hi) // 2
        if items[mid] < target:
            low = mid + 1
        else:
            hi = mid
    return low


def upper_bound(items, target):
    """First index whose value is > target (len(items) if none)."""
    lo = 0
    hi = len(items)
    while lo < hi:
        mid = (lo + hi) // 2
        if items[mid] < target:
            lo = mid + 1
        else:
            hi = mid
    return lo


def count_in_range(items, lo, hi):
    """How many values v satisfy lo <= v <= hi in the sorted list."""
    if lo > hi:
        return 0
    return upper_bound(items, hi) - lower_bound(items, lo)


def top_k(values, k):
    """The k largest values, largest first."""
    if k <= 0:
        return []
    return sorted(values, reverse=True)[:k]


def bottom_k(values, k):
    """The k smallest values, smallest first."""
    if k <= 0:
        return []
    return sorted(values)[:k]

"""Small text helpers."""

import re


def truncate(text, width, suffix="..."):
    """Shorten text to at most width characters, ending with suffix when cut."""
    if len(text) <= width:
        return text
    if width <= len(suffix):
        return suffix[:width]
    return text[: width - len(suffix)] + suffix


def slugify(text):
    """Lowercase, replace runs of non-alphanumerics with one hyphen, trim hyphens."""
    slug = re.sub(r"[^a-z0-9]+", "-", text.lower())
    return slug.strip("-")


def count_words(text):
    """Count whitespace-separated words."""
    return len(text.split())


def wrap(text, width):
    """Greedy word wrap; words longer than width get a line of their own."""
    lines = []
    current = ""
    for word in text.split():
        if not current:
            current = word
        elif len(current) + 1 + len(word) <= width:
            current = current + " " + word
        else:
            lines.append(current)
            current = word
    if current:
        lines.append(current)
    return lines


def common_prefix(strings):
    """Longest prefix shared by every string in the list."""
    if not strings:
        return ""
    prefix = strings[0]
    for s in strings[1:]:
        i = 0
        while i < len(prefix) and i <= len(s) and prefix[i] == s[i]:
            i += 1
        prefix = prefix[:i]
    return prefix


def is_palindrome(text):
    """True if the letters and digits read the same both ways, ignoring case."""
    letters = [c.lower() for c in text if c.isalnum()]
    left = 0
    right = len(letters) - 1
    while left < right:
        if letters[left] != letters[right]:
            return False
        left += 1
        right -= 1
    return True


def initials(name):
    """Uppercase initials of each word, e.g. 'ada lovelace' -> 'AL'."""
    return "".join(word[0].upper() for word in name.split() if word)

