"""Searching sorted lists."""


def binary_search(items, target):
    """Index of target in the sorted list, or -1."""
    lo = 0
    high = len(items) - 1
    while lo <= high:
        mid = (lo + high) // 2
        if items[mid] == target:
            return mid
        if items[mid] < target:
            lo = mid + 1
        else:
            high = mid - 1
    return -1


def lower_bound(items, target):
    """First index whose value is >= target (len(items) if none)."""
    lo = 0
    hi = len(items)
    while lo < hi:
        mid = (lo + hi) // 2
        if items[mid] < target:
            lo = mid + 1
        else:
            hi = mid
    return lo


def upper_bound(items, target):
    """First index whose value is > target (len(items) if none)."""
    lo = 0
    hi = len(items)
    while lo < hi:
        mid = (lo + hi) // 2
        if items[mid] <= target:
            lo = mid + 1
        else:
            hi = mid
    return lo


def count_in_range(items, lo, hi):
    """How many values v satisfy lo <= v <= hi in the sorted list."""
    if lo > hi:
        return 0
    return upper_bound(items, hi) - lower_bound(items, lo)


def top_k(values, k):
    """The k largest values, largest first."""
    if k <= 0:
        return []
    return sorted(values, reverse=True)[:k]


def contains_sorted(items, target):
    """True if target is in the sorted list."""
    i = lower_bound(items, target)
    return i < len(items) and items[i] == target

"""Descriptive statistics on lists of numbers."""


def mean(values):
    if not values:
        raise ValueError("mean of empty list")
    return sum(values) / len(values)


def median(values):
    if not values:
        raise ValueError("median of empty list")
    sorted_values = sorted(values)
    mid = len(sorted_values) // 2
    if len(sorted_values) % 2 == 1:
        return sorted_values[mid]
    return (sorted_values[mid - 1] + sorted_values[mid]) / 2


def variance(values, sample=True):
    """Sample variance by default (divides by n - 1); population variance otherwise."""
    n = len(values)
    if n < 2 and sample:
        raise ValueError("sample variance needs at least two values")
    m = mean(values)
    squares = sum((v - m) ** 2 for v in values)
    return squares / (n - 1) if sample else squares / n


def percentile(values, p):
    """Linear-interpolation percentile, p in [0, 100]."""
    if not values:
        raise ValueError("percentile of empty list")
    if p < 0 or p > 100:
        raise ValueError("p must be between 0 and 100")
    ordered = sorted(values)
    rank = (len(ordered) - 1) * p / 100
    low = int(rank)
    high = min(low + 1, len(ordered) - 1)
    weight = rank - low
    return ordered[low] + (ordered[high] - ordered[low]) * weight


def moving_average(values, window):
    """Averages of each full window of consecutive values."""
    if window <= 0:
        raise ValueError("window must be positive")
    result = []
    for i in range(len(values) - window + 1):
        chunk = values[i : i + window]
        result.append(sum(chunk) / window)
    return result


def clamp(x, lo, hi):
    if lo > hi:
        raise ValueError("lo must not exceed hi")
    if x < lo:
        return lo
    if x > hi:
        return hi
    return x


def mode(values):
    """Most frequent value; the smallest one wins ties."""
    if not values:
        raise ValueError("mode of empty list")
    counts = {}
    for v in values:
        counts[v] = counts.get(v, 0) + 1
    best = max(counts.values())
    return min(v for v, c in counts.items() if c == best)

